fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Calculate limit as usize (for indexing)
    let limit = usize::min(n as usize, participations.len());

    // Count the number of eligible participants
    let eligible_count = participations.iter()
        .take(limit)
        .filter(|&&attendance| 5 - attendance >= k)
        .count();

    // The number of teams of three that can be formed is eligible_count / 3
    (eligible_count / 3) as u8
}